const invName = env.get("INV_NAME");
const invIp = env.get("INV_IP");
const unitId = Number(env.get("INV_UNITID") || 1);
const startPLC = Number(env.get("START_PLC") || 40070);
const endPLC = Number(env.get("END_PLC") || 40096);

msg.payload = {
    fc: 3,
    unitid: unitId,
    address: startPLC - 1,
    quantity: endPLC - startPLC + 1
};

msg.meta = {
    inv: { name: invName, ip: invIp, unitid: unitId },
    startPLC,
    endPLC,
    ts: Math.floor(Date.now() / 1000)
};

return msg;

const meta = msg.meta || {};
const inv = meta.inv || { name: env.get("INV_NAME") };
const basePLC = meta.startPLC || 40070;

function getRegs(msg) {
    if (Array.isArray(msg.payload)) return msg.payload;
    if (msg.payload && Array.isArray(msg.payload.data)) return msg.payload.data;
    if (msg.responseBuffer && Array.isArray(msg.responseBuffer.data)) return msg.responseBuffer.data;
    return null;
}

const regs = getRegs(msg);

if (!regs || regs.length === 0) {
    const errMsg = `No data from ${inv.name}`;
    node.status({ fill: "red", shape: "ring", text: errMsg });
    msg.payload = { ok: false, error: errMsg, inv };
    return [null, msg];
}

function idx(a) { return a - basePLC; }
function u16(a) { const i = idx(a); if (i < 0 || i >= regs.length) return null; return Number(regs[i]) & 0xFFFF; }
function s16(a) { const v = u16(a); if (v === null) return null; return v > 0x7FFF ? v - 0x10000 : v; }
function u32SS(a) { const lo = u16(a), hi = u16(a+1); if (lo===null||hi===null) return null; return hi*65536+lo; }
function sf(raw, s) { if (raw===null||s===null) return null; return raw * Math.pow(10, s); }
function rnd(v, d) { d=d||3; if (v===null||v===undefined||Number.isNaN(v)) return null; const m=Math.pow(10,d); return Math.round(v*m)/m; }

try {
    const cSF=s16(40076), vSF=s16(40083), pSF=s16(40085), fSF=s16(40087);
    const vrSF=s16(40091), pfSF=s16(40093), eSF=s16(40096);
    const acW = sf(s16(40084), pSF);
    const acKW = acW===null ? null : acW/1000;
    const rVAr = sf(s16(40090), vrSF);
    const rKVAr = rVAr===null ? null : rVAr/1000;
    const pfPct = sf(s16(40092), pfSF);
    const eWh = sf(u32SS(40094), eSF);

    const result = {
        name: inv.name, type: 'INVERTER', ip: inv.ip, unitid: inv.unitid,
        ts: meta.ts || Math.floor(Date.now()/1000),
        model_did: u16(40070), model_length: u16(40071),
        Pinv_out_kw: rnd(acKW,3), Qinv_kvar: rnd(rKVAr,3),
        Ua_V: rnd(sf(u16(40080),vSF),2), Ub_V: rnd(sf(u16(40081),vSF),2), Uc_V: rnd(sf(u16(40082),vSF),2),
        Ia_A: rnd(sf(u16(40073),cSF),3), Ib_A: rnd(sf(u16(40074),cSF),3), Ic_A: rnd(sf(u16(40075),cSF),3),
        I_total_A: rnd(sf(u16(40072),cSF),3),
        frequency_Hz: rnd(sf(u16(40086),fSF),3),
        pf_percent: rnd(pfPct,3), power_factor: pfPct===null ? null : rnd(pfPct/100,4),
        Ainv_total_kWh: eWh===null ? null : rnd(eWh/1000,3),
        raw_registers: regs
    };

    // Lưu thẳng vào global context luôn
    global.set(inv.name, result);

    msg.payload = result;
    msg.topic = `inverter/${inv.name}`;
    node.status({ fill: 'green', shape: 'dot', text: `${inv.name}: ${rnd(acKW,1)||0}kW` });
    return [msg, null];
} catch (err) {
    node.status({ fill: 'red', shape: 'ring', text: err.message });
    msg.payload = { ok: false, error: err.message, inv };
    return [null, msg];
}
